extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody3D
	if not check("player", player != null, "Nella scena deve esserci il nodo Player"):
		return
	var lever := find_by_name(main, "Lever") as StaticBody3D
	if not check("lever", lever != null, "Nella scena deve esserci il nodo Lever"):
		return
	var label := find_by_name(player, "InteractionLabel") as Label
	if not check("label", label != null, "Il Player deve contenere l'etichetta InteractionLabel"):
		return
	var spring_arm := player.get_node_or_null("SpringArm3D") as Node3D
	if spring_arm != null:
		spring_arm.rotation = Vector3.ZERO
	player.rotation = Vector3.ZERO
	player.global_position = Vector3(0.0, 1.0, 0.0)
	player.velocity = Vector3.ZERO
	var ray := find_by_name(player, "RayCast3D") as RayCast3D
	if ray != null:
		ray.force_raycast_update()
	await wait_physics_frames(5)
	check("label_visible", label.text != "", "Guardando la leva, InteractionLabel deve mostrare la scritta d'interazione (trovato: '%s')" % label.text)
	var initial_state = lever.get("is_on")
	if initial_state == null:
		initial_state = false
	await tap_action("interact")
	await wait_physics_frames(5)
	var new_state = lever.get("is_on")
	if new_state == null:
		new_state = false
	check("lever_toggled", bool(new_state) != bool(initial_state), "Premendo il tasto 'interact' lo stato 'is_on' della leva deve cambiare (era %s, ora è %s)" % [str(initial_state), str(new_state)])
	player.rotation_degrees.y = 180.0
	if ray != null:
		ray.force_raycast_update()
	await wait_physics_frames(5)
	check("label_cleared", label.text == "", "Non guardando la leva, InteractionLabel deve svuotarsi (trovato: '%s')" % label.text)

